shortcuts.codeOnPrepare:
var raw = getVariable('shared_input').trim();
var urlMatch = raw.match(/https?:\/\/\S+/);
var locUrl = urlMatch ? urlMatch[0] : '';
var lines = raw.split('\n').map(function(s){return s.trim();}).filter(function(s){return s && s.indexOf('http') !== 0;});
var name = (lines.length > 0 ? lines[0] : raw);
function clean(s) {
  s = s.replace(/https?:\/\/\S+/g, '');
  s = s.replace(/\s*[-–—·|:,]?\s*Google Maps\s*$/i, '');
  s = s.replace(/[\s\-–—·|:,]+$/, '');
  s = s.replace(/^[\s\-–—·|:,]+/, '');
  return s.trim();
}
name = clean(name);
var cancelled = false, tag = '', rating = '', note = '', comments = '';
while (!name && !cancelled) {
  var redo = prompt('内容不能为空,重新输入:');
  if (redo !== null && redo.trim()) { name = redo.trim(); }
  else if (showSelection({'retry': '✏️ 重新输入', 'drop': '🗑 放弃,不写入'}) === 'drop') { showToast('已取消,未写入'); cancelled = true; }
}
if (!cancelled) {
  tag = showSelection(['Restaurant','Outdoors','Travel','Home','Exhibition','Show','Shops','Social','Concert','Study','Cafe'], 'Tag');
  if (tag === null) { showToast('已取消,未写入'); cancelled = true; }
}
if (!cancelled && tag === 'Restaurant') {
  var rate = showSelection({'good':'👍 推荐','ok':'😐 一般','bad':'👎 不行','skip':'➡️ 不评价'});
  rating = (rate === 'good') ? '👍 推荐' : (rate === 'ok') ? '😐 一般' : (rate === 'bad') ? '👎 不行' : '';
  if (rate && rate !== 'skip') {
    var n = prompt('一句话点评(可留空):', '');
    if (n !== null) note = n.trim();
  }
}
if (!cancelled) {
  var bits = [];
  if (rating) bits.push(rating);
  if (note) bits.push(note);
  comments = bits.join(' · ');
}
while (!cancelled) {
  var preview = name + ' · ' + tag + ' · 今天';
  if (comments) preview = preview + '\n📝 ' + comments;
  if (locUrl) preview = preview + '\n📍 (链接存入正文)';
  if (confirm('记入 Notion:\n' + preview)) { break; }
  var choice = showSelection({'edit': '✏️ 修改内容', 'drop': '🗑 放弃,不写入'});
  if (choice === 'drop') { showToast('已取消,未写入'); cancelled = true; }
  else if (choice === 'edit') {
    var edited = prompt('修改内容:', name);
    if (edited !== null && edited.trim()) { name = edited.trim(); }
  }
}
if (cancelled) { abort(); }
else {
  var children = locUrl ? [{"object":"block","type":"paragraph","paragraph":{"rich_text":[{"type":"text","text":{"content":"📍 在地图打开","link":{"url":locUrl}}}]}}] : [];
  setVariable('clean_name', name);
  setVariable('clean_tag', tag);
  setVariable('clean_comments', comments);
  setVariable('body_children', JSON.stringify(children));
}

